"""Few-but-large differential cases: long journal walks, big blocks, deep branches."""
import json, random, sys, time
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/dev')
import scheduler, ref as refmod
from adapter import execute_batch

def make(seed):
    rng = random.Random(seed)
    U = 1 << 22
    M = rng.randint(1, 3); L = rng.randint(1, 3)
    R = rng.randint(1, 6)
    borders = [0] + sorted(rng.sample(range(1, U), R - 1)) + [U] if R > 1 else [0, U]
    kind = rng.choice(['fifo','sp','sff','wfq'])
    flows = list(range(4))
    if kind == 'sp':
        policy = {'kind':'sp','levels':[[f, rng.randrange(U)] for f in flows]}
    elif kind == 'wfq':
        policy = {'kind':'wfq','weights':[[f, rng.randint(1,1024)] for f in flows]}
    else:
        policy = {'kind':kind}
    ev=[]; nid=0; saved=[]
    n = rng.randint(1500, 3500)
    while len(ev) < n:
        pick = rng.random()
        if pick < 0.45:
            ev.append(['enqueue', nid, rng.choice(flows), rng.randint(1, 400), rng.randrange(U)]); nid += 1
        elif pick < 0.66:
            ev.append(['dequeue', rng.randint(1, 12)])
        elif pick < 0.72:
            ev.append(['sample'])
        elif pick < 0.77:
            k = rng.randint(1, R + 3)
            ev.append(['repartition', [0] + sorted(rng.sample(range(1, U), k - 1)) + [U] if k > 1 else [0, U]])
        elif pick < 0.83:
            ev.append(['cancel', rng.randrange(0, nid + 5)])
        elif pick < 0.89:
            ev.append(['inspect', rng.randrange(0, nid + 5)])
        elif pick < 0.95:
            name = rng.randrange(5)
            ev.append(['save', name]); saved.append(name)
        elif saved:
            ev.append(['restore', rng.choice(saved)])
    return {'runs':[{ 'banks':M,'load_balancers':L,'fifo_bytes':rng.choice([2000,10**6]),
                      'pifo_bytes':rng.choice([1500,10**6]),'refill_batch':rng.choice([1,4,32]),
                      'sample_period':rng.choice([1,7,500]),'borders':borders,
                      'policy':policy,'events':ev}]}

def main():
    lo, hi = int(sys.argv[1]), int(sys.argv[2])
    for seed in range(lo, hi):
        req = make(seed)
        t=time.time(); mine = json.loads(json.dumps(execute_batch(req))); dt=time.time()-t
        t=time.time(); theirs = json.loads(json.dumps(refmod.run_batch(req))); dt2=time.time()-t
        status = 'ok' if mine == theirs else 'MISMATCH'
        print('seed %d engine %.2fs ref %.2fs %s' % (seed, dt, dt2, status))
        if status != 'ok':
            json.dump(req, open('/workspace/dev/fail_scale_%d.json'%seed,'w'))
            a,b = mine['runs'][0], theirs['runs'][0]
            for j in range(min(len(a['log']),len(b['log']))):
                if a['log'][j]!=b['log'][j]:
                    print('  row',j,a['log'][j],b['log'][j]); break
            else:
                print('  stateA', json.dumps(a['state'])[:700]); print('  stateB', json.dumps(b['state'])[:700])
            return 1
    return 0

sys.exit(main())
